// Shared plane-translation interaction for section teaching models.
// Pointer Events support mouse, pen and touch; only a handle or explicit edit mode intercepts orbit gestures.
export function installPlaneDrag({THREE,viewer,controls,getCamera,getState,setPosition,getPlaneMesh,onMode}){
 const handles=Array.from({length:4},(_,i)=>{const b=document.createElement('button');b.className='plane-drag-handle plane-edge-handle';b.type='button';b.setAttribute('aria-label','拖曳剖切面邊框，方向鍵亦可調整');b.title='拖曳剖面邊框；方向鍵微調';b.textContent='✥';viewer.append(b);return b;});const handle=handles[0];
 const edge=document.createElementNS('http://www.w3.org/2000/svg','svg');edge.classList.add('plane-edge-overlay');edge.setAttribute('aria-hidden','true');const outline=document.createElementNS(edge.namespaceURI,'polygon');edge.append(outline);viewer.append(edge);
 const badge=document.createElement('div');badge.className='drag-status';badge.setAttribute('role','status');badge.setAttribute('aria-live','polite');viewer.append(badge);
 let editing=false,active=null;const ray=new THREE.Raycaster();
 function mode(on){editing=on;viewer.classList.toggle('plane-edit-mode',on);onMode?.(on);refresh();}
 function project(p,camera){const q=p.clone().project(camera),r=viewer.getBoundingClientRect();return {x:(q.x+1)*r.width/2,y:(1-q.y)*r.height/2,z:q.z};}
 function refresh(){const s=getState(),camera=getCamera(),mesh=getPlaneMesh();camera.updateMatrixWorld();mesh.updateMatrixWorld();const w=viewer.clientWidth,h=viewer.clientHeight;let poly=[[-8,-8,0],[8,-8,0],[8,8,0],[-8,8,0]].map(p=>project(new THREE.Vector3(...p).applyMatrix4(mesh.matrixWorld),camera));
 // Clip the projected plane to an inset viewport, keeping perimeter controls visible.
 for(const [key,bound,sign] of [['x',24,1],['x',w-24,-1],['y',24,1],['y',h-70,-1]]){const out=[];for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],ai=(a[key]-bound)*sign>=0,bi=(b[key]-bound)*sign>=0;if(ai)out.push(a);if(ai!==bi){const t=(bound-a[key])/(b[key]-a[key]);out.push({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t});}}poly=out;}
 const visible=editing&&s.enabled&&mesh.visible&&poly.length>1;edge.style.display=visible?'block':'none';edge.setAttribute('viewBox',`0 0 ${w} ${h}`);outline.setAttribute('points',poly.map(p=>p.x+','+p.y).join(' '));
 handles.forEach((b,i)=>{b.hidden=!visible;const k=Math.floor(i*poly.length/4);let p=poly[k]||{x:0,y:0};if(p.x>w-85&&p.y<125){const q=poly[(k+1)%poly.length];if(q){p={x:(p.x+q.x)/2,y:(p.y+q.y)/2};}}b.style.left=p.x+'px';b.style.top=p.y+'px';});
 badge.textContent=active?'正在移動剖切面 · 放開即完成':editing?'拖曳剖面或邊框標記 · 旋轉已暫停':'拖曳旋轉模型；切換右上方剖面圖示可移動切面';}
 function hit(e){const r=viewer.getBoundingClientRect();ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),getCamera());const mesh=getPlaneMesh();mesh.updateMatrixWorld();return ray.intersectObject(mesh,false).length>0;}
 function down(e){if(e.target.closest?.('.viewer-tools')||active||e.button!==0)return;const s=getState();if(!s.enabled)return;const viaHandle=handles.includes(e.target)||e.target===outline;if(!viaHandle&&(!editing||!hit(e)))return;e.preventDefault();e.stopPropagation();const camera=getCamera(),a=project(s.center,camera),dir=new THREE.Vector3().setComponent(s.axis,1),b=project(s.center.clone().add(dir),camera),dx=b.x-a.x,dy=b.y-a.y,l2=dx*dx+dy*dy;active={pointer:e.pointerId,x:e.clientX,y:e.clientY,start:s.position,dx,dy,l2,extent:s.max-s.min,oldEnabled:controls.enabled};controls.enabled=false;viewer.setPointerCapture(e.pointerId);viewer.classList.add('dragging-plane');refresh();}
 function move(e){if(!active||active.pointer!==e.pointerId)return;e.preventDefault();e.stopPropagation();const a=active,dx=e.clientX-a.x,dy=e.clientY-a.y;const delta=a.l2>9?(dx*a.dx+dy*a.dy)/a.l2/a.extent*100:-dy/Math.max(160,viewer.clientHeight*.65)*100;setPosition(Math.round(Math.max(0,Math.min(100,a.start+delta))*10)/10);refresh();}
 function end(e){if(!active||(e?.pointerId!==undefined&&e.pointerId!==active.pointer))return;const a=active;active=null;if(viewer.hasPointerCapture(a.pointer))viewer.releasePointerCapture(a.pointer);controls.enabled=editing?false:a.oldEnabled;viewer.classList.remove('dragging-plane');refresh();}
 viewer.addEventListener('pointerdown',down,true);viewer.addEventListener('pointermove',move,true);viewer.addEventListener('pointerup',end,true);viewer.addEventListener('pointercancel',end,true);viewer.addEventListener('lostpointercapture',end,true);window.addEventListener('blur',()=>end());
 handles.forEach(handle=>handle.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowDown','ArrowRight','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const s=getState(),v=e.key==='Home'?0:e.key==='End'?100:s.position+(['ArrowLeft','ArrowDown'].includes(e.key)?-1:1)*(e.shiftKey?5:0.5);setPosition(Math.max(0,Math.min(100,v)));refresh();}}));
 return {refresh,setMode(on){if(active)end();controls.enabled=!on;mode(on);},get editing(){return editing;}};
}
